-- Disposable PostgreSQL only: no real review, file, order or payment.
\set ON_ERROR_STOP on
BEGIN;
SELECT id AS review_request FROM private.kinto_deletion_requests_v1 WHERE customer_id='00000000-0000-4000-8000-000000000002' \gset
SELECT public.kinto_privacy_admin_v1('test-admin','deletions',:'review_request','verify','TEST review account verified');
SELECT id AS target_review FROM public.product_reviews WHERE customer_id='00000000-0000-4000-8000-000000000002'LIMIT 1 \gset
INSERT INTO public.orders VALUES('00000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000001','تم التسليم','{}');
INSERT INTO public.product_reviews(id,customer_id,order_id,store_id,product_reference,product_name_snapshot,rating,comment)VALUES('00000000-0000-4000-8000-000000000051','00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000041','00000000-0000-4000-8000-000000000010','TEST-other','TEST other customer',3,'TEST preserve other review');
INSERT INTO public.product_review_helpful_votes(review_id,visitor_hash)VALUES(:'target_review',digest('TEST anonymous visitor','sha256')),('00000000-0000-4000-8000-000000000051',digest('TEST other visitor','sha256'));
CREATE TEMP TABLE review_preserved AS SELECT(SELECT jsonb_agg(to_jsonb(o)ORDER BY id)FROM public.orders o)orders,(SELECT to_jsonb(r)FROM public.product_reviews r WHERE id='00000000-0000-4000-8000-000000000051')other_review,(SELECT to_jsonb(v)FROM public.product_review_helpful_votes v WHERE review_id='00000000-0000-4000-8000-000000000051')other_vote;
SELECT private.kinto_privacy_review_hash_v1(to_jsonb(r))AS review_hash FROM public.product_reviews r WHERE id=:'target_review' \gset
UPDATE private.kinto_erasure_policy_v1 SET inventory_signature=private.kinto_erasure_signature_v1(),enabled=false;
SELECT public.test_assert(jsonb_array_length(public.kinto_privacy_review_record_v1('test-admin',:'review_request'))=1,'review list scopes selected account');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_record_v1(%L,%L,%L,%L,%L,%L)','test-admin',:'review_request','approve_erase',:'target_review',:'review_hash','TEST reviewed nonfinancial content'),'POLICY_OR_INVENTORY_NOT_VERIFIED');
UPDATE private.kinto_erasure_policy_v1 SET enabled=true;
SELECT public.test_assert(NOT has_function_privilege('anon','public.kinto_privacy_review_erase_v1(text,uuid,uuid,uuid)','EXECUTE'),'browser cannot execute review erasure directly');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_record_v1(%L,%L)','test-TEST-A',:'review_request'),'ADMIN_SESSION_INVALID');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_record_v1(%L,%L,%L,%L)','test-admin',:'review_request','detail','00000000-0000-4000-8000-000000000051'),'OWNED_PRODUCT_REVIEW_REQUIRED');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_record_v1(%L,%L,NULL)','test-admin',:'review_request'),'INVALID_REVIEW_PRIVACY_ACTION');
SELECT public.kinto_privacy_review_record_v1('test-admin',:'review_request','retain',:'target_review',:'review_hash','TEST keep until specific case reviewed',now()+interval '30 days');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_ERASURE_APPROVAL_REQUIRED');
SELECT public.kinto_privacy_review_record_v1('test-admin',:'review_request','approve_erase',:'target_review',:'review_hash','TEST nonfinancial review deletion approved');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review','00000000-0000-4000-8000-000000000051'),'EXACT_REVIEW_CONFIRMATION_REQUIRED');
SAVEPOINT changed_review;
UPDATE public.product_reviews SET comment='TEST changed after approval'WHERE id=:'target_review';
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_CONTENT_CHANGED');
ROLLBACK TO changed_review;
SAVEPOINT remaining_image;
INSERT INTO public.product_review_images(review_id,storage_path,mime_type,byte_size)VALUES(:'target_review','reviews/'||:'target_review'||'/TEST-remains.png','image/png',12);
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_MEDIA_CLEANUP_REQUIRED');
ROLLBACK TO remaining_image;
SAVEPOINT unused_upload;
INSERT INTO private.product_review_upload_tickets_v150(review_id,customer_id,storage_path,mime_type,byte_size,expires_at)VALUES(:'target_review','00000000-0000-4000-8000-000000000002','reviews/'||:'target_review'||'/TEST-unused.png','image/png',12,now()-interval '1 day');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_MEDIA_CLEANUP_REQUIRED');
ROLLBACK TO unused_upload;
SAVEPOINT unresolved_report;
INSERT INTO private.kinto_review_reports_v1(customer_id,review_id,kind,reason)VALUES('00000000-0000-4000-8000-000000000001',:'target_review','user','other');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'OPEN_REVIEW_REPORT_REQUIRES_RESOLUTION');
ROLLBACK TO unresolved_report;
SAVEPOINT unknown_child;
CREATE TABLE public.test_unreviewed_review_child(review_id uuid REFERENCES public.product_reviews(id)ON DELETE CASCADE,amount numeric);
INSERT INTO public.test_unreviewed_review_child VALUES(:'target_review',500);
UPDATE private.kinto_erasure_policy_v1 SET inventory_signature=private.kinto_erasure_signature_v1();
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_ERASURE_SCHEMA_NOT_VERIFIED');
SELECT public.test_assert((SELECT amount FROM public.test_unreviewed_review_child)=500,'unknown financial child not cascaded');
ROLLBACK TO unknown_child;
SAVEPOINT empty_child_statement_trigger;
CREATE FUNCTION private.test_review_image_delete_trigger()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN RAISE EXCEPTION 'UNSAFE_EMPTY_CHILD_DELETE';END$$;
CREATE TRIGGER test_review_image_statement AFTER DELETE ON public.product_review_images FOR EACH STATEMENT EXECUTE FUNCTION private.test_review_image_delete_trigger();
UPDATE private.kinto_erasure_policy_v1 SET inventory_signature=private.kinto_erasure_signature_v1();
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_ERASURE_SCHEMA_NOT_VERIFIED');
ROLLBACK TO empty_child_statement_trigger;
SAVEPOINT forced_child_rls;
ALTER TABLE public.product_review_images FORCE ROW LEVEL SECURITY;
UPDATE private.kinto_erasure_policy_v1 SET inventory_signature=private.kinto_erasure_signature_v1();
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'REVIEW_ERASURE_SCHEMA_NOT_VERIFIED');
ROLLBACK TO forced_child_rls;
SAVEPOINT receipt_failure;
CREATE FUNCTION private.test_review_receipt_failure()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.state='erased'THEN RAISE EXCEPTION 'TEST_REVIEW_RECEIPT_FAILURE';END IF;RETURN NEW;END$$;
CREATE TRIGGER test_review_receipt BEFORE UPDATE ON private.kinto_privacy_review_decisions_v1 FOR EACH ROW EXECUTE FUNCTION private.test_review_receipt_failure();
UPDATE private.kinto_erasure_policy_v1 SET inventory_signature=private.kinto_erasure_signature_v1();
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'TEST_REVIEW_RECEIPT_FAILURE');
SELECT public.test_assert(EXISTS(SELECT 1 FROM public.product_reviews WHERE id=:'target_review')AND EXISTS(SELECT 1 FROM public.product_review_helpful_votes WHERE review_id=:'target_review'),'receipt failure restores review and cascaded votes');
SELECT public.test_assert((SELECT state FROM private.kinto_privacy_review_decisions_v1 WHERE review_id=:'target_review')='approved','failed receipt creates no false erased evidence');
ROLLBACK TO receipt_failure;
SET ROLE service_role;
SELECT public.kinto_privacy_review_erase_v1('test-admin',:'review_request',:'target_review',:'target_review');
RESET ROLE;
SELECT public.test_assert(NOT EXISTS(SELECT 1 FROM public.product_reviews WHERE id=:'target_review')AND NOT EXISTS(SELECT 1 FROM public.product_review_helpful_votes WHERE review_id=:'target_review'),'only approved review and its context-bound helpful votes removed');
SELECT public.test_assert(public.kinto_privacy_review_erase_v1('test-admin',:'review_request',:'target_review',:'target_review')->>'duplicate'='true','review completion idempotent');
SELECT public.test_assert((SELECT note IS NULL AND erased_key_hash IS NOT NULL FROM private.kinto_privacy_review_decisions_v1 WHERE review_id=:'target_review'),'minimal completion omits private approval note');
SELECT public.test_assert((private.kinto_privacy_checkpoint_v1()->>'payload_text')::jsonb->'counts'->>'review_records'='1','coherent checkpoint includes completed review deletion');
SELECT public.test_denied($q$SELECT public.kinto_deletion_request_v1('test-TEST-B','cancel')$q$,'PRIVACY_DELETION_ALREADY_STARTED');
SELECT public.test_denied(format('INSERT INTO private.kinto_review_reports_v1(customer_id,review_id,kind,reason)VALUES(%L,%L,%L,%L)','00000000-0000-4000-8000-000000000001',:'target_review','user','other'),'REVIEW_REPORT_TARGET_CHANGED');
INSERT INTO public.product_reviews(id,customer_id,order_id,store_id,product_reference,product_name_snapshot,rating,comment)VALUES(:'target_review','00000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000030','00000000-0000-4000-8000-000000000010','TEST restored copy','TEST restored review',5,'TEST earlier restored version');
SELECT public.test_denied(format('SELECT public.kinto_privacy_review_erase_v1(%L,%L,%L,%L)','test-admin',:'review_request',:'target_review',:'target_review'),'ERASED_REVIEW_REAPPEARED');
SELECT public.test_assert(jsonb_array_length(private.kinto_privacy_restore_review_matches_v1((SELECT jsonb_build_array(erased_key_hash)FROM private.kinto_privacy_review_decisions_v1 WHERE review_id=:'target_review'))->'matched_hashes')=1,'external hash detects restored older review without comment export');
SELECT public.test_assert((SELECT orders FROM review_preserved)=(SELECT jsonb_agg(to_jsonb(o)ORDER BY id)FROM public.orders o),'all orders unchanged');
SELECT public.test_assert((SELECT other_review FROM review_preserved)=(SELECT to_jsonb(r)FROM public.product_reviews r WHERE id='00000000-0000-4000-8000-000000000051'),'other customer review unchanged');
SELECT public.test_assert((SELECT other_vote FROM review_preserved)=(SELECT to_jsonb(v)FROM public.product_review_helpful_votes v WHERE review_id='00000000-0000-4000-8000-000000000051'),'other review vote unchanged');
ROLLBACK;
SELECT 'PASS_REVIEW_RECORD_ERASURE: approved exact-owned review and dependent votes removed, media/tickets/reports/schema/stale holds, receipt rollback, external restored-review detection, other reviews and orders unchanged';
